-- =====================================================================
-- Locale_403.lua — v4.0.3 release notes and feature highlights
-- =====================================================================

TomoMod_RegisterLocale("enUS", {
    ["wn_403_quest_journal_skin_removed"] = "Removed — The experimental Quest Journal and World Map skin has been removed because it caused errors in game. Blizzard's original journal visuals and behaviour remain untouched; the independent World Quests tab is still available.",
    ["wn_403_world_quest_tab"] = "Changed — The former World Quest panel beside the world map has been replaced by a native World Quests tab inside the Quest Journal, keeping quests and map navigation in one window.",
    ["wn_403_world_quest_cards"] = "New — World Quests are displayed as compact cards with reward icons, rarity accents, elite markers, zone and remaining time. Search, sorting by time, reward, zone or name, a draggable scrollbar and one-click map navigation are built in.",
    ["wn_403_world_quest_sort"] = "Fixed — World Quest sorting now tolerates missing or non-numeric times, reward data and quest IDs. Empty entries are ordered consistently, equal values use a deterministic quest-ID tie-break and both ascending and descending paths are explicit.",
    ["wn_403_bags_separate_skin"] = "New — Separate bag mode keeps Blizzard's individual container windows and gives them a complete TomoMod skin: dark panels and headers, azure borders, Poppins titles, recessed slots, cropped icons and accent feedback on hover. Returning to combined mode or disabling Bags restores the original native artwork.",
    ["wn_403_bags_tracked_currencies"] = "New — The Bags V4 sidebar now lists every currency marked Show in Backpack in compact two-column tiles with its icon, formatted quantity and native tooltip. The localized section appears only when currencies are tracked and refreshes whenever currency data changes.",
    ["wn_403_bags_currency_reliability"] = "Fixed — Hiding Blizzard's backpack in combined mode could reduce its calculated watched-currency capacity to one. TomoMod now preserves the traditional three slots only in that mode and reads the persisted isShowInBackpack state directly, so additional tracked currencies no longer disappear.",
    ["wn_403_color_picker_skin"] = "New — Blizzard's global colour picker now has a complete TomoMod skin with layered dark body, header and footer surfaces, azure borders, Poppins typography and themed controls. The hex field, colour swatches, value and alpha areas and opacity slider all share the same visual language.",
    ["wn_403_color_picker_compatibility"] = "Changed — The skin supports both the current Retail and legacy ColorPickerFrame layouts, initializes when Blizzard's load-on-demand picker becomes available and reapplies whenever it opens. Blizzard still owns colour selection, confirmation and cancellation callbacks.",
    ["wn_403_color_picker_buttons"] = "Fixed — Retail panel buttons no longer repaint their persistent Left, Middle and Right background textures over the TomoMod skin. The custom close control also preserves Blizzard's original cancellation callback and previous colour values.",
    ["wn_403_waypoint_inner_ring"] = "Changed — The waypoint beacon now keeps only its compact inner ring. The oversized translucent outer glow and its colour and size updates have been removed for a cleaner marker, while the beam, centre dot and navigation arrow retain their existing behaviour.",
    ["wn_403_mplus_cast_focus"] = "New — The Mythic+ Studio gains an opt-in experimental Cast-focus nameplates setting, disabled by default. In an active key with at least two meaningful engaged trash enemies, a cast or channel keeps its source visible while temporarily fading the other engaged trash plates.",
    ["wn_403_mplus_cast_focus_safety"] = "Changed — Target and focus always remain visible, bosses and friendly units are never filtered, and tanks keep enemies with missing or low threat on screen. Every plate is restored immediately when no cast is active or the option is disabled.",
    ["wn_403_mplus_cast_focus_runtime"] = "Internal — Cast focus changes only the alpha of TomoMod's visual child, never Blizzard's protected nameplate or click area. Its lightweight runtime lives in the always-loaded Nameplates module, so the load-on-demand Mythic+ Studio does not need to remain open during combat.",
    ["wn_403_survival_tab"] = "New — Mythic+ Run Analysis gains a Survival tab next to the Summary. Both views share the same window, so the run summary, group performance and splits stay one click away from the death analysis.",
    ["wn_403_survival_chronology"] = "New — The Survival tab lists every death recorded during the key in chronological order, with its run time and the player's class colour. Selecting a row opens that death in the detail panel.",
    ["wn_403_survival_detail"] = "New — Your own deaths are shown in full: the fatal event with its icon, name, damage and overkill, your maximum health, and the last ten events before you died, each with the time separating it from the killing blow and the health you had left.",
    ["wn_403_survival_collector"] = "New — The death collector now loads with TomoMod itself instead of the load-on-demand Mythic+ Studio. Tracking begins when the key begins, so a run is never lost because the Studio had not been opened yet.",
    ["wn_403_survival_unit_events"] = "Changed — Deaths are read from unit-state transitions rather than the combat log, which is protected on the current client. Group health and flag events give the same chronology without touching it.",
    ["wn_403_survival_recap_bridge"] = "Changed — Your pre-death timeline is copied from Blizzard's death recap through the guarded TomoDamageMeter bridge. The recap is not readable the instant you die, so it is retried for about two and a half seconds before the death is marked as having no readable detail.",
    ["wn_403_survival_reliability"] = "Changed — The number of deaths observed is cross-checked against the game's own count for the key. A matching run is reported as complete tracking, while a key joined late or reloaded mid-run is reported as partial tracking with both figures, instead of presenting an incomplete list as the whole story.",
    ["wn_403_survival_history"] = "New — The death chronology is stored in the run snapshot alongside the existing performance data, so reopening a past key from Run History shows the deaths that run actually had instead of nothing at all.",
    ["wn_403_survival_localization"] = "Changed — Every label of the Survival tab — the tabs themselves, the chronology, the tracking state, the fatal event, the timeline and the messages shown when no detail is available — is translated in all six supported languages.",
    ["wn_403_bags_secure_clicks"] = "Fixed — Bags V4 no longer attaches addon mouse, click or drag handlers to Blizzard's protected container item buttons. The native template remains the sole owner of item use and tooltips, preventing ordinary right-clicks from triggering ADDON_ACTION_FORBIDDEN.",
    ["wn_403_tomohdv_studio"] = "New — TomoHDV is now integrated as a native Auction House tab with Search, Recipes and AH Scan workspaces. The former floating Recipe Tracker is retired while its saved prices and tooltip compatibility remain available.",
    ["wn_403_tomohdv_workflows"] = "New — Search shows recent queries, quantities, current minimums and stored scan prices with direct access to Blizzard's Buy view. Tracked recipe sheets list reagent unit and total prices and can search a component with one click.",
    ["wn_403_tomohdv_scan"] = "New — Full Auction House scans store the lowest observed unit price for every item, display processing progress and respect Blizzard's 15-minute replicate-scan cooldown.",
    ["wn_403_tomohdv_polish"] = "Changed — TomoHDV V2 gains centred navigation, persistent selection accents, flexible columns, responsive search and recipe panels, price cards and a clearer scan-progress layout.",
    ["wn_403_tomohdv_safety"] = "Fixed — The TomoHDV tab anchors safely to Blizzard's last native tab. Global tooltip customizers now skip sensitive embedded Auction House, World Map and Quest tooltips to avoid contaminating protected UI paths.",
    ["wn_403_tomohdv_direct_buy"] = "New — TomoHDV V3 lets you buy straight from the item sheet. Selecting a search result queries Blizzard's live offers and shows the auction type, a quantity field, the estimated total and a status line, so a purchase no longer requires leaving the tab.",
    ["wn_403_tomohdv_buy_quote"] = "New — Commodity totals come from Blizzard's own quantity aggregation, so the price shown is the real cost of consuming several stacked offers. A Max control fills in everything available, while an ordinary auction resolves to the cheapest listing that is not your own.",
    ["wn_403_tomohdv_buy_safety"] = "Changed — The quote is recalculated inside the click itself, just before the protected call, so a price that moved cannot be bought at a stale total. Blizzard still owns the confirmation dialog, which opens above TomoHDV.",
    ["wn_403_tomohdv_buy_live"] = "Changed — The purchase panel follows live Auction House traffic: search updates refresh the quote in place, a completed purchase re-queries the remaining offers, and a failed one says so and disables the button until a fresh quote arrives.",
    ["wn_403_tomohdv_selection_layout"] = "Changed — The selected result keeps a persistent azure accent through list refreshes, the former Open in Buy button is gone now that the purchase happens in place, and the columns and price cards have been rebalanced to make room for the new panel.",
    ["wn_403_tomohdv_overflow"] = "Fixed — TomoHDV V3.1 keeps the complete direct-purchase block inside the item sheet at every supported Auction House height. Quantity, total, status and buy controls no longer overflow below the panel.",
    ["wn_403_tomohdv_text_limits"] = "Fixed — Buttons, recent searches, prices, quantities, auction types and status messages now respect their available width and line count. Item names use at most two lines and the responsive detail sheet scales from 340 to 400 pixels.",
    ["wn_403_lustsound_audio"] = "Changed — LustSound now respects the selected WoW audio channel, the current sound-enabled state and master volume. The Force Sound option was removed, and TomoMod no longer changes global audio CVars when the alert starts or stops.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_403_quest_journal_skin_removed"] = "Suppression — L'habillage expérimental du Journal de quêtes et de la carte du monde a été retiré parce qu'il provoquait des erreurs en jeu. L'apparence et le comportement Blizzard restent intacts ; l'onglet indépendant des quêtes mondiales reste disponible.",
    ["wn_403_world_quest_tab"] = "Modification — L'ancien panneau des quêtes mondiales placé à côté de la carte est remplacé par un onglet natif dans le Journal de quêtes, réunissant les quêtes et la navigation sur la carte dans une même fenêtre.",
    ["wn_403_world_quest_cards"] = "Nouveauté — Les quêtes mondiales s'affichent sous forme de cartes compactes avec icône de récompense, couleur de rareté, marqueur élite, zone et temps restant. La recherche, le tri par temps, récompense, zone ou nom, la barre de défilement et l'accès direct à la carte sont intégrés.",
    ["wn_403_world_quest_sort"] = "Correction — Le tri des quêtes mondiales accepte désormais les temps, récompenses et identifiants de quête manquants ou non numériques. Les entrées vides sont classées de façon cohérente, les valeurs identiques sont départagées par l'identifiant et les deux sens de tri sont explicites.",
    ["wn_403_bags_separate_skin"] = "Nouveauté — Le mode sacs séparés conserve les fenêtres individuelles de Blizzard et leur applique un habillage TomoMod complet : panneaux et en-têtes sombres, bordures azur, titres Poppins, cases en retrait, icônes recadrées et accent au survol. Revenir au mode combiné ou désactiver les sacs restaure l'apparence native d'origine.",
    ["wn_403_bags_tracked_currencies"] = "Nouveauté — La barre latérale de Bags V4 liste maintenant chaque monnaie marquée Afficher dans le sac à dos sous forme de vignettes compactes sur deux colonnes, avec son icône, sa quantité formatée et son infobulle native. Cette section localisée apparaît uniquement lorsque des monnaies sont suivies et s'actualise avec leurs données.",
    ["wn_403_bags_currency_reliability"] = "Correction — Masquer le sac à dos Blizzard en mode combiné pouvait réduire à une seule la capacité calculée des monnaies suivies. TomoMod préserve désormais les trois emplacements habituels uniquement dans ce mode et lit directement l'état persistant isShowInBackpack, afin que les monnaies supplémentaires ne disparaissent plus.",
    ["wn_403_color_picker_skin"] = "Nouveauté — Le sélecteur de couleurs global de Blizzard dispose maintenant d'un habillage TomoMod complet avec corps, en-tête et pied de page sombres superposés, bordures azur, police Poppins et commandes assorties. Le champ hexadécimal, les aperçus, les zones de valeur et d'alpha ainsi que le curseur d'opacité partagent la même identité visuelle.",
    ["wn_403_color_picker_compatibility"] = "Modification — L'habillage prend en charge les versions Retail actuelle et héritée de ColorPickerFrame, s'initialise lorsque le sélecteur Blizzard à chargement différé devient disponible et se réapplique à chaque ouverture. Blizzard conserve la sélection de couleur et les callbacks de validation et d'annulation.",
    ["wn_403_color_picker_buttons"] = "Correction — Les boutons de panneau Retail ne redessinent plus leurs textures persistantes Left, Middle et Right par-dessus l'habillage TomoMod. Le bouton de fermeture personnalisé conserve également le callback d'annulation Blizzard et les valeurs de couleur précédentes.",
    ["wn_403_waypoint_inner_ring"] = "Modification — La balise de point de passage conserve uniquement son anneau intérieur compact. Le grand halo extérieur translucide et ses mises à jour de couleur et de taille ont été supprimés pour obtenir un repère plus net, tandis que le faisceau, le point central et la flèche de navigation gardent leur comportement actuel.",
    ["wn_403_mplus_cast_focus"] = "Nouveauté — Le Studio Mythic+ reçoit une option expérimentale facultative Nameplates focalisées sur les casts, désactivée par défaut. Dans une clé active avec au moins deux trashs significatifs engagés, un cast ou une canalisation garde sa source visible et estompe temporairement les autres plaques engagées.",
    ["wn_403_mplus_cast_focus_safety"] = "Modification — La cible et le focus restent toujours visibles, les boss et unités amicales ne sont jamais filtrés, et les tanks conservent à l'écran les ennemis sans menace ou avec une menace faible. Toutes les plaques sont restaurées dès qu'aucun cast n'est actif ou que l'option est désactivée.",
    ["wn_403_mplus_cast_focus_runtime"] = "Interne — La focalisation modifie uniquement l'opacité de l'élément visuel TomoMod, jamais la nameplate protégée ni la zone cliquable de Blizzard. Son moteur léger réside dans le module Nameplates toujours chargé ; le Studio Mythic+ à chargement différé n'a donc pas besoin de rester ouvert en combat.",
    ["wn_403_survival_tab"] = "Nouveauté — L'Analyse de run Mythic+ gagne un onglet Survie à côté du Résumé. Les deux vues partagent la même fenêtre : le résumé du run, les performances du groupe et les splits restent à un clic de l'analyse des morts.",
    ["wn_403_survival_chronology"] = "Nouveauté — L'onglet Survie liste chaque mort enregistrée pendant la clé, dans l'ordre chronologique, avec son temps de run et la couleur de classe du joueur. Sélectionner une ligne ouvre cette mort dans le panneau de détail.",
    ["wn_403_survival_detail"] = "Nouveauté — Tes propres morts sont détaillées : l'événement fatal avec son icône, son nom, ses dégâts et son overkill, ta vie maximale, et les dix derniers événements avant ta mort, chacun avec le temps qui le sépare du coup fatal et la vie qu'il te restait.",
    ["wn_403_survival_collector"] = "Nouveauté — Le collecteur de morts est désormais chargé avec TomoMod lui-même et non avec le Studio Mythic+ à la demande. Le suivi démarre en même temps que la clé : un run n'est plus perdu parce que le Studio n'avait pas encore été ouvert.",
    ["wn_403_survival_unit_events"] = "Modification — Les morts sont lues à partir des transitions d'état des unités plutôt que du journal de combat, protégé sur le client actuel. Les événements de vie et d'indicateurs du groupe donnent la même chronologie sans y toucher.",
    ["wn_403_survival_recap_bridge"] = "Modification — Ta chronologie d'avant-mort est copiée depuis le récapitulatif de mort de Blizzard via le pont protégé de TomoDamageMeter. Ce récapitulatif n'est pas lisible à l'instant de la mort : il est donc réessayé pendant environ deux secondes et demie avant que la mort soit marquée comme sans détail lisible.",
    ["wn_403_survival_reliability"] = "Modification — Le nombre de morts observées est recoupé avec le compteur du jeu pour la clé. Un run cohérent est annoncé en suivi complet ; une clé rejointe en cours ou rechargée en plein run est annoncée en suivi partiel avec les deux chiffres, plutôt que de présenter une liste incomplète comme si elle était complète.",
    ["wn_403_survival_history"] = "Nouveauté — La chronologie des morts est stockée dans l'instantané du run, à côté des données de performance existantes : rouvrir une ancienne clé depuis l'Historique des runs affiche les morts que ce run a réellement eues au lieu de rien du tout.",
    ["wn_403_survival_localization"] = "Modification — Tous les libellés de l'onglet Survie — les onglets eux-mêmes, la chronologie, l'état du suivi, l'événement fatal, la timeline et les messages affichés en l'absence de détail — sont traduits dans les six langues prises en charge.",
    ["wn_403_bags_secure_clicks"] = "Correction — Bags V4 n'ajoute plus de gestionnaires de souris, de clic ou de glisser-déposer aux boutons d'objets protégés de Blizzard. Le modèle natif reste seul responsable de l'utilisation et des infobulles, évitant qu'un clic droit ordinaire déclenche ADDON_ACTION_FORBIDDEN.",
    ["wn_403_tomohdv_studio"] = "Nouveauté — TomoHDV est désormais intégré comme onglet natif de l'Hôtel des ventes avec les espaces Recherche, Recettes et Scan HDV. L'ancien suivi flottant est retiré, tandis que ses prix mémorisés et ses infobulles restent disponibles.",
    ["wn_403_tomohdv_workflows"] = "Nouveauté — La recherche affiche les requêtes récentes, les quantités, les prix minimums actuels et les prix scannés, avec accès direct à la vue Achat de Blizzard. Les fiches de recettes suivies détaillent les prix unitaires et totaux des composants et permettent d'en rechercher un en un clic.",
    ["wn_403_tomohdv_scan"] = "Nouveauté — Les scans complets de l'Hôtel des ventes mémorisent le prix unitaire le plus bas de chaque objet, affichent leur progression et respectent le délai Blizzard de 15 minutes entre deux scans répliqués.",
    ["wn_403_tomohdv_polish"] = "Modification — TomoHDV V2 reçoit une navigation centrée, des sélections persistantes, des colonnes flexibles, des panneaux Recherche et Recettes adaptatifs, des cartes de prix et une progression de scan plus lisible.",
    ["wn_403_tomohdv_safety"] = "Correction — L'onglet TomoHDV s'ancre correctement au dernier onglet natif de Blizzard. Les personnalisations globales ignorent maintenant les infobulles intégrées sensibles de l'Hôtel des ventes, de la carte et des quêtes afin de ne pas contaminer les chemins d'interface protégés.",
    ["wn_403_tomohdv_direct_buy"] = "Nouveauté — TomoHDV V3 permet d'acheter directement depuis la fiche objet. Sélectionner un résultat interroge les offres actuelles de Blizzard et affiche le type de vente, un champ de quantité, le total estimé et une ligne d'état : plus besoin de quitter l'onglet pour acheter.",
    ["wn_403_tomohdv_buy_quote"] = "Nouveauté — Le total des composants passe par l'agrégation de quantité de Blizzard : le prix affiché correspond au coût réel de plusieurs offres empilées. Un bouton Max reprend tout ce qui est disponible, tandis qu'un objet classique se résout à la vente la moins chère qui ne vous appartient pas.",
    ["wn_403_tomohdv_buy_safety"] = "Modification — Le devis est recalculé dans le clic lui-même, juste avant l'appel protégé : un prix qui a bougé ne peut pas être payé sur un total périmé. La fenêtre de confirmation reste celle de Blizzard et s'ouvre au-dessus de TomoHDV.",
    ["wn_403_tomohdv_buy_live"] = "Modification — Le panneau d'achat suit l'activité de l'Hôtel des ventes : les mises à jour de recherche actualisent le devis sur place, un achat réussi réinterroge les offres restantes, et un achat échoué le signale et désactive le bouton jusqu'au devis suivant.",
    ["wn_403_tomohdv_selection_layout"] = "Modification — Le résultat sélectionné conserve son liseré azur pendant les rafraîchissements, l'ancien bouton Ouvrir dans Achat disparaît puisque l'achat se fait sur place, et les colonnes et cartes de prix ont été rééquilibrées pour laisser la place au nouveau panneau.",
    ["wn_403_tomohdv_overflow"] = "Correction — TomoHDV V3.1 maintient tout le bloc d'achat direct dans la fiche objet, quelle que soit la hauteur prise en charge de l'Hôtel des ventes. Les contrôles de quantité, total, état et achat ne débordent plus sous le panneau.",
    ["wn_403_tomohdv_text_limits"] = "Correction — Les boutons, recherches récentes, prix, quantités, types de vente et messages d'état respectent maintenant la largeur et le nombre de lignes disponibles. Les noms d'objet utilisent au plus deux lignes et la fiche adaptative mesure entre 340 et 400 pixels.",
    ["wn_403_lustsound_audio"] = "Modification — LustSound respecte désormais le canal audio WoW sélectionné, l'état actuel du son et le volume principal. L'option Forcer le son a été supprimée et TomoMod ne modifie plus les CVars audio globales au démarrage ou à l'arrêt de l'alerte.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_403_quest_journal_skin_removed"] = "Entfernt — Der experimentelle Skin für Questtagebuch und Weltkarte wurde entfernt, weil er im Spiel Fehler verursachte. Blizzards ursprüngliche Darstellung und Funktion bleiben unangetastet; der unabhängige Weltquests-Reiter ist weiterhin verfügbar.",
    ["wn_403_world_quest_tab"] = "Geändert — Das bisherige Weltquest-Fenster neben der Weltkarte wurde durch einen nativen Weltquests-Reiter im Questtagebuch ersetzt. Quests und Kartennavigation befinden sich damit in einem gemeinsamen Fenster.",
    ["wn_403_world_quest_cards"] = "Neu — Weltquests erscheinen als kompakte Karten mit Belohnungssymbol, Seltenheitsfarbe, Elite-Markierung, Zone und verbleibender Zeit. Suche, Sortierung nach Zeit, Belohnung, Zone oder Name, eine ziehbare Bildlaufleiste und Kartennavigation per Klick sind integriert.",
    ["wn_403_world_quest_sort"] = "Behoben — Die Sortierung der Weltquests verträgt jetzt fehlende oder nicht numerische Zeiten, Belohnungsdaten und Quest-IDs. Leere Einträge werden einheitlich eingeordnet, gleiche Werte eindeutig über die Quest-ID entschieden und beide Sortierrichtungen ausdrücklich behandelt.",
    ["wn_403_bags_separate_skin"] = "Neu — Der Modus für getrennte Taschen behält Blizzards einzelne Behälterfenster und versieht sie mit einem vollständigen TomoMod-Skin: dunkle Flächen und Kopfzeilen, azurblaue Ränder, Poppins-Titel, vertiefte Plätze, beschnittene Symbole und Akzent beim Überfahren. Beim Wechsel zurück zum kombinierten Modus oder Deaktivieren der Taschen wird die ursprüngliche Gestaltung wiederhergestellt.",
    ["wn_403_bags_tracked_currencies"] = "Neu — Die Seitenleiste von Bags V4 zeigt jetzt jede mit Im Rucksack anzeigen markierte Währung als kompakte Kachel in zwei Spalten mit Symbol, formatierter Menge und nativem Tooltip. Der lokalisierte Bereich erscheint nur bei verfolgten Währungen und wird bei Änderungen der Währungsdaten aktualisiert.",
    ["wn_403_bags_currency_reliability"] = "Behoben — Das Ausblenden von Blizzards Rucksack im kombinierten Modus konnte die berechnete Kapazität verfolgter Währungen auf eine reduzieren. TomoMod bewahrt nur in diesem Modus die üblichen drei Plätze und liest den gespeicherten Status isShowInBackpack direkt, sodass weitere verfolgte Währungen nicht mehr verschwinden.",
    ["wn_403_color_picker_skin"] = "Neu — Blizzards globaler Farbwähler besitzt jetzt einen vollständigen TomoMod-Skin mit gestaffelten dunklen Flächen für Inhalt, Kopf- und Fußzeile, azurblauen Rändern, Poppins-Schrift und passenden Bedienelementen. Hexadezimalfeld, Farbvorschauen, Wert- und Alphabereich sowie Deckkraftregler folgen derselben Gestaltung.",
    ["wn_403_color_picker_compatibility"] = "Geändert — Der Skin unterstützt sowohl das aktuelle Retail- als auch das ältere ColorPickerFrame-Layout, initialisiert sich beim Laden von Blizzards verzögertem Farbwähler und wird bei jedem Öffnen erneut angewendet. Farbauswahl sowie Bestätigungs- und Abbruchrückrufe bleiben vollständig bei Blizzard.",
    ["wn_403_color_picker_buttons"] = "Behoben — Retail-Schaltflächen zeichnen ihre dauerhaften Hintergrundtexturen Left, Middle und Right nicht mehr über den TomoMod-Skin. Auch die eigene Schließen-Schaltfläche bewahrt Blizzards ursprünglichen Abbruchrückruf und die vorherigen Farbwerte.",
    ["wn_403_waypoint_inner_ring"] = "Geändert — Die Wegpunktmarkierung behält nur noch ihren kompakten inneren Ring. Der große durchscheinende Außenleuchtring samt Farb- und Größenanpassung wurde für eine klarere Markierung entfernt; Strahl, Mittelpunkt und Navigationspfeil funktionieren unverändert weiter.",
    ["wn_403_mplus_cast_focus"] = "Neu — Das Mythic+-Studio erhält die optionale experimentelle Einstellung Zauberfokus-Namensplaketten, die standardmäßig ausgeschaltet ist. In einem aktiven Schlüssel mit mindestens zwei wichtigen beteiligten Trash-Gegnern bleibt bei einem Zauber oder Kanal dessen Quelle sichtbar, während die anderen beteiligten Trash-Plaketten vorübergehend ausgeblendet werden.",
    ["wn_403_mplus_cast_focus_safety"] = "Geändert — Ziel und Fokus bleiben immer sichtbar, Bosse und freundliche Einheiten werden nie gefiltert, und Tanks sehen weiterhin Gegner mit fehlender oder geringer Bedrohung. Sobald kein Zauber mehr aktiv oder die Option ausgeschaltet ist, werden alle Plaketten sofort wiederhergestellt.",
    ["wn_403_mplus_cast_focus_runtime"] = "Intern — Der Zauberfokus ändert nur die Transparenz des visuellen TomoMod-Kindelements, niemals Blizzards geschützte Namensplakette oder Klickfläche. Die schlanke Laufzeit liegt im stets geladenen Namensplakettenmodul; das nachladbare Mythic+-Studio muss im Kampf nicht geöffnet bleiben.",
    ["wn_403_survival_tab"] = "Neu — Die Mythic+-Runanalyse erhält neben der Übersicht einen Reiter Überleben. Beide Ansichten teilen sich dasselbe Fenster, sodass Runzusammenfassung, Gruppenleistung und Splits nur einen Klick von der Todesanalyse entfernt bleiben.",
    ["wn_403_survival_chronology"] = "Neu — Der Reiter Überleben listet jeden während des Schlüssels erfassten Tod in chronologischer Reihenfolge auf, mit Runzeit und Klassenfarbe des Spielers. Ein Klick auf eine Zeile öffnet diesen Tod im Detailbereich.",
    ["wn_403_survival_detail"] = "Neu — Deine eigenen Tode werden vollständig dargestellt: das tödliche Ereignis mit Symbol, Name, Schaden und Overkill, deine maximale Gesundheit sowie die letzten zehn Ereignisse vor deinem Tod, jeweils mit dem Abstand zum tödlichen Treffer und der verbliebenen Gesundheit.",
    ["wn_403_survival_collector"] = "Neu — Der Todessammler wird jetzt mit TomoMod selbst geladen statt mit dem nachladbaren Mythic+-Studio. Die Erfassung startet mit dem Schlüssel, sodass kein Run mehr verloren geht, nur weil das Studio noch nicht geöffnet war.",
    ["wn_403_survival_unit_events"] = "Geändert — Tode werden aus Zustandswechseln der Einheiten gelesen statt aus dem Kampflog, das auf dem aktuellen Client geschützt ist. Gesundheits- und Flag-Ereignisse der Gruppe liefern dieselbe Chronologie, ohne es anzufassen.",
    ["wn_403_survival_recap_bridge"] = "Geändert — Deine Ereigniskette vor dem Tod wird über die abgesicherte TomoDamageMeter-Brücke aus Blizzards Todesrückblick kopiert. Der Rückblick ist im Moment des Todes noch nicht lesbar und wird daher rund zweieinhalb Sekunden lang erneut abgefragt, bevor der Tod als ohne lesbare Details markiert wird.",
    ["wn_403_survival_reliability"] = "Geändert — Die Zahl der beobachteten Tode wird mit dem spieleigenen Zähler des Schlüssels abgeglichen. Ein übereinstimmender Run wird als vollständige Erfassung gemeldet, ein spät betretener oder mitten im Run neu geladener Schlüssel dagegen als teilweise Erfassung mit beiden Werten — statt eine unvollständige Liste als das Ganze auszugeben.",
    ["wn_403_survival_history"] = "Neu — Die Todeschronologie wird zusammen mit den bestehenden Leistungsdaten im Run-Schnappschuss gespeichert. Das erneute Öffnen eines früheren Schlüssels aus dem Runverlauf zeigt damit die Tode, die dieser Run tatsächlich hatte, statt gar nichts.",
    ["wn_403_survival_localization"] = "Geändert — Sämtliche Beschriftungen des Reiters Überleben — die Reiter selbst, die Chronologie, der Erfassungsstatus, das tödliche Ereignis, die Zeitleiste und die Hinweise bei fehlenden Details — sind in allen sechs unterstützten Sprachen übersetzt.",
    ["wn_403_bags_secure_clicks"] = "Behoben — Bags V4 hängt keine eigenen Maus-, Klick- oder Ziehfunktionen mehr an Blizzards geschützte Gegenstandsschaltflächen. Die native Vorlage bleibt allein für Gegenstandsbenutzung und Tooltips zuständig, damit ein normaler Rechtsklick kein ADDON_ACTION_FORBIDDEN mehr auslöst.",
    ["wn_403_tomohdv_studio"] = "Neu — TomoHDV ist jetzt als nativer Auktionshaus-Reiter mit den Bereichen Suche, Rezepte und AH-Scan integriert. Der frühere schwebende Rezept-Tracker entfällt, seine gespeicherten Preise und Tooltip-Kompatibilität bleiben erhalten.",
    ["wn_403_tomohdv_workflows"] = "Neu — Die Suche zeigt letzte Anfragen, Mengen, aktuelle Mindestpreise und gespeicherte Scanpreise mit direktem Zugriff auf Blizzards Kaufen-Ansicht. Verfolgte Rezepte führen Stück- und Gesamtpreise der Reagenzien auf und können eine Zutat mit einem Klick suchen.",
    ["wn_403_tomohdv_scan"] = "Neu — Vollständige Auktionshaus-Scans speichern für jeden Gegenstand den niedrigsten beobachteten Stückpreis, zeigen den Fortschritt an und beachten Blizzards 15-minütige Wartezeit für Replikationsscans.",
    ["wn_403_tomohdv_polish"] = "Geändert — TomoHDV V2 erhält eine zentrierte Navigation, dauerhafte Auswahlmarkierungen, flexible Spalten, responsive Such- und Rezeptbereiche, Preiskarten und eine übersichtlichere Scanfortschrittsanzeige.",
    ["wn_403_tomohdv_safety"] = "Behoben — Der TomoHDV-Reiter wird sicher an Blizzards letzten nativen Reiter angehängt. Globale Tooltip-Anpassungen überspringen jetzt empfindliche eingebettete Tooltips von Auktionshaus, Weltkarte und Quests, damit geschützte UI-Pfade nicht verunreinigt werden.",
    ["wn_403_tomohdv_direct_buy"] = "Neu — TomoHDV V3 erlaubt den Kauf direkt aus der Gegenstandsansicht. Die Auswahl eines Ergebnisses fragt Blizzards aktuelle Angebote ab und zeigt Auktionsart, ein Mengenfeld, die geschätzte Summe und eine Statuszeile, sodass der Reiter zum Kaufen nicht mehr verlassen werden muss.",
    ["wn_403_tomohdv_buy_quote"] = "Neu — Summen für Handelswaren stammen aus Blizzards eigener Mengenaggregation und geben die tatsächlichen Kosten mehrerer gestapelter Angebote wieder. Eine Max-Schaltfläche übernimmt alles Verfügbare, während eine gewöhnliche Auktion auf das günstigste fremde Angebot aufgelöst wird.",
    ["wn_403_tomohdv_buy_safety"] = "Änderung — Das Angebot wird im Klick selbst neu berechnet, unmittelbar vor dem geschützten Aufruf, damit ein zwischenzeitlich geänderter Preis nicht zu einer veralteten Summe gekauft wird. Die Bestätigung bleibt Blizzards Dialog und öffnet sich über TomoHDV.",
    ["wn_403_tomohdv_buy_live"] = "Änderung — Das Kauffenster folgt dem laufenden Auktionshausverkehr: Suchaktualisierungen erneuern das Angebot an Ort und Stelle, ein abgeschlossener Kauf fragt die verbleibenden Angebote erneut ab, und ein fehlgeschlagener meldet dies und deaktiviert die Schaltfläche bis zum nächsten Angebot.",
    ["wn_403_tomohdv_selection_layout"] = "Änderung — Das ausgewählte Ergebnis behält seinen azurblauen Akzent über Aktualisierungen hinweg, die frühere Schaltfläche In Kaufen öffnen entfällt, da der Kauf nun an Ort und Stelle geschieht, und Spalten sowie Preiskarten wurden für das neue Fenster neu ausbalanciert.",
    ["wn_403_tomohdv_overflow"] = "Behoben — TomoHDV V3.1 hält den vollständigen Direktkaufbereich bei jeder unterstützten Auktionshaushöhe innerhalb der Gegenstandsansicht. Mengen-, Summen-, Status- und Kaufelemente ragen nicht mehr unter das Fenster hinaus.",
    ["wn_403_tomohdv_text_limits"] = "Behoben — Schaltflächen, letzte Suchen, Preise, Mengen, Auktionsarten und Statusmeldungen halten sich jetzt an verfügbare Breite und Zeilenzahl. Gegenstandsnamen nutzen höchstens zwei Zeilen und die responsive Detailansicht skaliert von 340 bis 400 Pixeln.",
    ["wn_403_lustsound_audio"] = "Geändert — LustSound beachtet jetzt den gewählten WoW-Audiokanal, den aktuellen Soundstatus und die Gesamtlautstärke. Die Option Sound erzwingen wurde entfernt; TomoMod verändert beim Starten oder Stoppen des Hinweises keine globalen Audio-CVars mehr.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_403_quest_journal_skin_removed"] = "Eliminado — El diseño experimental del Diario de misiones y del mapa del mundo se ha retirado porque provocaba errores en el juego. El aspecto y el comportamiento originales de Blizzard permanecen intactos; la pestaña independiente de misiones de mundo sigue disponible.",
    ["wn_403_world_quest_tab"] = "Cambio — El antiguo panel de misiones de mundo situado junto al mapa ha sido sustituido por una pestaña nativa dentro del Diario de misiones, reuniendo las misiones y la navegación del mapa en una sola ventana.",
    ["wn_403_world_quest_cards"] = "Novedad — Las misiones de mundo se muestran como tarjetas compactas con icono de recompensa, color de rareza, marcador de élite, zona y tiempo restante. Incluyen búsqueda, orden por tiempo, recompensa, zona o nombre, barra de desplazamiento arrastrable y navegación al mapa con un clic.",
    ["wn_403_world_quest_sort"] = "Corrección — La ordenación de misiones de mundo admite ahora tiempos, datos de recompensa e identificadores de misión ausentes o no numéricos. Las entradas vacías se colocan de forma coherente, los valores iguales se resuelven por identificador y ambos sentidos de ordenación son explícitos.",
    ["wn_403_bags_separate_skin"] = "Novedad — El modo de bolsas separadas conserva las ventanas individuales de Blizzard y les aplica un diseño TomoMod completo: paneles y cabeceras oscuros, bordes azules, títulos Poppins, casillas hundidas, iconos recortados y realce al pasar el cursor. Volver al modo combinado o desactivar las bolsas restaura el aspecto nativo original.",
    ["wn_403_bags_tracked_currencies"] = "Novedad — La barra lateral de Bags V4 muestra ahora cada moneda marcada Mostrar en la mochila en mosaicos compactos de dos columnas, con icono, cantidad formateada y descripción nativa. La sección localizada aparece solo cuando hay monedas seguidas y se actualiza al cambiar sus datos.",
    ["wn_403_bags_currency_reliability"] = "Corrección — Ocultar la mochila de Blizzard en modo combinado podía reducir a una la capacidad calculada de monedas seguidas. TomoMod conserva ahora los tres espacios habituales solo en ese modo y lee directamente el estado persistente isShowInBackpack, para que las monedas adicionales dejen de desaparecer.",
    ["wn_403_color_picker_skin"] = "Novedad — El selector de color global de Blizzard cuenta ahora con un diseño TomoMod completo, con cuerpo, cabecera y pie oscuros en capas, bordes azules, tipografía Poppins y controles a juego. El campo hexadecimal, las muestras de color, las zonas de valor y alfa y el control de opacidad comparten el mismo estilo.",
    ["wn_403_color_picker_compatibility"] = "Cambio — El diseño admite tanto la disposición Retail actual como la heredada de ColorPickerFrame, se inicializa cuando está disponible el selector de Blizzard de carga bajo demanda y vuelve a aplicarse cada vez que se abre. Blizzard conserva la selección del color y las funciones de confirmación y cancelación.",
    ["wn_403_color_picker_buttons"] = "Corrección — Los botones de panel Retail ya no dibujan sus texturas persistentes Left, Middle y Right sobre el diseño TomoMod. El botón de cierre personalizado también conserva la función de cancelación original de Blizzard y los valores de color anteriores.",
    ["wn_403_waypoint_inner_ring"] = "Cambio — La baliza del punto de ruta conserva únicamente su anillo interior compacto. El gran halo exterior translúcido y sus ajustes de color y tamaño se han eliminado para ofrecer un marcador más limpio, mientras que el haz, el punto central y la flecha de navegación mantienen su comportamiento actual.",
    ["wn_403_mplus_cast_focus"] = "Novedad — El Estudio Mítica+ incorpora la opción experimental Placas centradas en lanzamientos, desactivada de forma predeterminada. En una llave activa con al menos dos enemigos de trash relevantes en combate, un lanzamiento o canalización mantiene visible a su origen y atenúa temporalmente las demás placas de trash en combate.",
    ["wn_403_mplus_cast_focus_safety"] = "Cambio — El objetivo y el foco permanecen siempre visibles, los jefes y las unidades amistosas nunca se filtran y los tanques siguen viendo a los enemigos sin amenaza o con amenaza baja. Todas las placas se restauran inmediatamente cuando no hay lanzamientos activos o se desactiva la opción.",
    ["wn_403_mplus_cast_focus_runtime"] = "Interno — El foco de lanzamientos solo cambia la opacidad del elemento visual de TomoMod, nunca la placa protegida ni el área de clic de Blizzard. Su ejecución ligera reside en el módulo Placas siempre cargado, por lo que el Estudio Mítica+ de carga bajo demanda no necesita seguir abierto durante el combate.",
    ["wn_403_survival_tab"] = "Novedad — El Análisis de run Mítica+ incorpora una pestaña Supervivencia junto al Resumen. Ambas vistas comparten la misma ventana, así que el resumen del run, el rendimiento del grupo y los splits quedan a un clic del análisis de muertes.",
    ["wn_403_survival_chronology"] = "Novedad — La pestaña Supervivencia enumera cada muerte registrada durante la llave en orden cronológico, con su tiempo de run y el color de clase del jugador. Al seleccionar una fila se abre esa muerte en el panel de detalle.",
    ["wn_403_survival_detail"] = "Novedad — Tus propias muertes se muestran al completo: el evento fatal con su icono, nombre, daño y overkill, tu salud máxima y los diez últimos eventos antes de morir, cada uno con el tiempo que lo separa del golpe mortal y la salud que te quedaba.",
    ["wn_403_survival_collector"] = "Novedad — El recolector de muertes ahora se carga con el propio TomoMod en lugar del Estudio Mítica+ bajo demanda. El seguimiento empieza con la llave, de modo que ya no se pierde un run porque el Estudio no se hubiera abierto todavía.",
    ["wn_403_survival_unit_events"] = "Cambio — Las muertes se leen a partir de las transiciones de estado de las unidades y no del registro de combate, protegido en el cliente actual. Los eventos de salud e indicadores del grupo ofrecen la misma cronología sin tocarlo.",
    ["wn_403_survival_recap_bridge"] = "Cambio — Tu cronología previa a la muerte se copia del resumen de muerte de Blizzard a través del puente protegido de TomoDamageMeter. Ese resumen no es legible en el instante de morir, así que se reintenta durante unos dos segundos y medio antes de marcar la muerte como sin detalle legible.",
    ["wn_403_survival_reliability"] = "Cambio — El número de muertes observadas se contrasta con el propio contador del juego para la llave. Un run coincidente se informa como seguimiento completo, mientras que una llave iniciada tarde o recargada a mitad de run se informa como seguimiento parcial con ambas cifras, en lugar de presentar una lista incompleta como si fuera toda la historia.",
    ["wn_403_survival_history"] = "Novedad — La cronología de muertes se guarda en la instantánea del run junto a los datos de rendimiento existentes, así que reabrir una llave antigua desde el Historial de runs muestra las muertes que ese run tuvo realmente en vez de nada.",
    ["wn_403_survival_localization"] = "Cambio — Todas las etiquetas de la pestaña Supervivencia — las propias pestañas, la cronología, el estado del seguimiento, el evento fatal, la línea temporal y los mensajes que aparecen cuando no hay detalle — están traducidas a los seis idiomas compatibles.",
    ["wn_403_bags_secure_clicks"] = "Corrección — Bags V4 ya no añade controladores propios de ratón, clic o arrastre a los botones de objetos protegidos de Blizzard. La plantilla nativa conserva en exclusiva el uso de objetos y los tooltips, evitando que un clic derecho normal provoque ADDON_ACTION_FORBIDDEN.",
    ["wn_403_tomohdv_studio"] = "Novedad — TomoHDV está integrado como pestaña nativa de la Casa de Subastas con espacios de Buscar, Recetas y Escaneo. El antiguo rastreador flotante se retira, pero sus precios guardados y la compatibilidad con tooltips se conservan.",
    ["wn_403_tomohdv_workflows"] = "Novedad — La búsqueda muestra consultas recientes, cantidades, precios mínimos actuales y precios escaneados, con acceso directo a la vista Comprar de Blizzard. Las fichas de recetas seguidas detallan los precios unitarios y totales de los componentes y permiten buscar uno con un clic.",
    ["wn_403_tomohdv_scan"] = "Novedad — Los escaneos completos de la Casa de Subastas guardan el menor precio unitario observado de cada objeto, muestran el progreso y respetan el intervalo de 15 minutos de Blizzard entre escaneos replicados.",
    ["wn_403_tomohdv_polish"] = "Cambio — TomoHDV V2 incorpora navegación centrada, selección persistente, columnas flexibles, paneles adaptables de búsqueda y recetas, tarjetas de precios y un progreso de escaneo más claro.",
    ["wn_403_tomohdv_safety"] = "Corrección — La pestaña TomoHDV se ancla de forma segura a la última pestaña nativa de Blizzard. Las personalizaciones globales omiten ahora los tooltips integrados sensibles de la Casa de Subastas, el mapa y las misiones para no contaminar rutas de interfaz protegidas.",
    ["wn_403_tomohdv_direct_buy"] = "Novedad — TomoHDV V3 permite comprar directamente desde la ficha del objeto. Seleccionar un resultado consulta las ofertas actuales de Blizzard y muestra el tipo de subasta, un campo de cantidad, el total estimado y una línea de estado, sin salir de la pestaña.",
    ["wn_403_tomohdv_buy_quote"] = "Novedad — El total de los componentes usa la agregación de cantidad de Blizzard, así que el precio mostrado es el coste real de consumir varias ofertas apiladas. Un botón Máx. toma todo lo disponible, mientras que una subasta normal se resuelve en la oferta más barata que no sea tuya.",
    ["wn_403_tomohdv_buy_safety"] = "Cambio — El presupuesto se recalcula dentro del propio clic, justo antes de la llamada protegida, para que un precio que se haya movido no se compre con un total obsoleto. La confirmación sigue siendo la de Blizzard y se abre sobre TomoHDV.",
    ["wn_403_tomohdv_buy_live"] = "Cambio — El panel de compra sigue la actividad de la Casa de Subastas: las actualizaciones de búsqueda refrescan la oferta en el sitio, una compra completada vuelve a consultar las ofertas restantes y una fallida lo indica y desactiva el botón hasta la siguiente oferta.",
    ["wn_403_tomohdv_selection_layout"] = "Cambio — El resultado seleccionado conserva su acento azul durante los refrescos, el antiguo botón Abrir en Comprar desaparece porque la compra ocurre en el sitio, y las columnas y tarjetas de precio se han reequilibrado para dejar espacio al nuevo panel.",
    ["wn_403_tomohdv_overflow"] = "Corrección — TomoHDV V3.1 mantiene todo el bloque de compra directa dentro de la ficha del objeto con cualquier altura compatible de la Casa de Subastas. Los controles de cantidad, total, estado y compra ya no sobresalen por debajo del panel.",
    ["wn_403_tomohdv_text_limits"] = "Corrección — Los botones, búsquedas recientes, precios, cantidades, tipos de subasta y mensajes de estado respetan ahora el ancho y el número de líneas disponibles. Los nombres usan como máximo dos líneas y la ficha adaptable escala entre 340 y 400 píxeles.",
    ["wn_403_lustsound_audio"] = "Cambio — LustSound respeta ahora el canal de audio de WoW seleccionado, el estado actual del sonido y el volumen maestro. Se eliminó la opción Forzar sonido y TomoMod ya no cambia las CVars globales de audio al iniciar o detener la alerta.",
})

TomoMod_RegisterLocale("itIT", {
    ["wn_403_quest_journal_skin_removed"] = "Rimosso — Lo stile sperimentale del Registro missioni e della mappa del mondo è stato rimosso perché causava errori nel gioco. L'aspetto e il comportamento originali di Blizzard restano invariati; la scheda indipendente delle missioni mondiali è ancora disponibile.",
    ["wn_403_world_quest_tab"] = "Modifica — Il precedente pannello delle missioni mondiali accanto alla mappa è stato sostituito da una scheda nativa nel Registro missioni, riunendo missioni e navigazione della mappa in un'unica finestra.",
    ["wn_403_world_quest_cards"] = "Novità — Le missioni mondiali sono mostrate come schede compatte con icona della ricompensa, colore di rarità, indicatore élite, zona e tempo rimanente. Sono inclusi ricerca, ordinamento per tempo, ricompensa, zona o nome, barra di scorrimento trascinabile e navigazione sulla mappa con un clic.",
    ["wn_403_world_quest_sort"] = "Correzione — L'ordinamento delle missioni mondiali ora gestisce tempi, dati delle ricompense e ID missione mancanti o non numerici. Le voci vuote vengono ordinate in modo coerente, i valori uguali sono risolti tramite l'ID missione ed entrambi i versi di ordinamento sono espliciti.",
    ["wn_403_bags_separate_skin"] = "Novità — La modalità con borse separate mantiene le singole finestre contenitore di Blizzard e applica uno stile TomoMod completo: pannelli e intestazioni scuri, bordi azzurri, titoli Poppins, slot incassati, icone ritagliate e risalto al passaggio. Tornando alla modalità combinata o disattivando le borse viene ripristinato l'aspetto nativo originale.",
    ["wn_403_bags_tracked_currencies"] = "Novità — La barra laterale di Bags V4 elenca ora ogni valuta contrassegnata Mostra nello zaino in riquadri compatti su due colonne, con icona, quantità formattata e tooltip nativo. La sezione localizzata appare solo quando ci sono valute tracciate e si aggiorna al variare dei loro dati.",
    ["wn_403_bags_currency_reliability"] = "Correzione — Nascondere lo zaino Blizzard in modalità combinata poteva ridurre a uno la capacità calcolata delle valute tracciate. TomoMod mantiene ora i tre spazi tradizionali soltanto in questa modalità e legge direttamente lo stato persistente isShowInBackpack, così le valute aggiuntive non scompaiono più.",
    ["wn_403_color_picker_skin"] = "Novità — Il selettore colore globale di Blizzard dispone ora di uno stile TomoMod completo, con corpo, intestazione e piè di pagina scuri a livelli, bordi azzurri, carattere Poppins e controlli coordinati. Campo esadecimale, campioni colore, aree valore e alfa e cursore di opacità condividono lo stesso aspetto.",
    ["wn_403_color_picker_compatibility"] = "Modifica — Lo stile supporta sia il layout Retail attuale sia quello precedente di ColorPickerFrame, si inizializza quando il selettore Blizzard a caricamento differito diventa disponibile e viene riapplicato a ogni apertura. La selezione del colore e le funzioni di conferma e annullamento restano gestite da Blizzard.",
    ["wn_403_color_picker_buttons"] = "Correzione — I pulsanti dei pannelli Retail non ridisegnano più le texture persistenti Left, Middle e Right sopra lo stile TomoMod. Anche il pulsante di chiusura personalizzato conserva la funzione di annullamento originale di Blizzard e i valori colore precedenti.",
    ["wn_403_waypoint_inner_ring"] = "Modifica — Il segnalatore del punto di navigazione mantiene soltanto il suo anello interno compatto. Il grande alone esterno traslucido e i relativi aggiornamenti di colore e dimensione sono stati rimossi per un indicatore più pulito, mentre il raggio, il punto centrale e la freccia di navigazione conservano il comportamento attuale.",
    ["wn_403_mplus_cast_focus"] = "Novità — Lo Studio Mitica+ riceve l'opzione sperimentale Barre focalizzate sui cast, disattivata per impostazione predefinita. In una chiave attiva con almeno due nemici trash significativi ingaggiati, un lancio o una canalizzazione mantiene visibile la sua origine e attenua temporaneamente le altre barre dei trash ingaggiati.",
    ["wn_403_mplus_cast_focus_safety"] = "Modifica — Bersaglio e focus restano sempre visibili, boss e unità amiche non vengono mai filtrati e i tank continuano a vedere i nemici senza minaccia o con minaccia bassa. Tutte le barre vengono ripristinate subito quando non ci sono cast attivi o l'opzione viene disattivata.",
    ["wn_403_mplus_cast_focus_runtime"] = "Interno — La focalizzazione sui cast modifica soltanto l'opacità dell'elemento visivo TomoMod, mai la barra protetta o l'area cliccabile di Blizzard. Il motore leggero risiede nel modulo Nameplates sempre caricato, quindi lo Studio Mitica+ a caricamento differito non deve rimanere aperto durante il combattimento.",
    ["wn_403_survival_tab"] = "Novità — L'Analisi run Mitica+ guadagna una scheda Sopravvivenza accanto al Riepilogo. Le due viste condividono la stessa finestra, così riepilogo della run, prestazioni del gruppo e split restano a un clic dall'analisi delle morti.",
    ["wn_403_survival_chronology"] = "Novità — La scheda Sopravvivenza elenca ogni morte registrata durante la chiave in ordine cronologico, con il suo tempo di run e il colore di classe del giocatore. Selezionando una riga si apre quella morte nel pannello di dettaglio.",
    ["wn_403_survival_detail"] = "Novità — Le tue morti sono mostrate per intero: l'evento fatale con icona, nome, danni e overkill, la tua salute massima e gli ultimi dieci eventi prima della morte, ciascuno con il tempo che lo separa dal colpo fatale e la salute che ti restava.",
    ["wn_403_survival_collector"] = "Novità — Il raccoglitore di morti viene ora caricato con TomoMod stesso anziché con lo Studio Mitica+ a richiesta. Il tracciamento parte insieme alla chiave, quindi una run non va più persa perché lo Studio non era ancora stato aperto.",
    ["wn_403_survival_unit_events"] = "Modifica — Le morti sono lette dalle transizioni di stato delle unità anziché dal registro di combattimento, protetto sul client attuale. Gli eventi di salute e di stato del gruppo forniscono la stessa cronologia senza toccarlo.",
    ["wn_403_survival_recap_bridge"] = "Modifica — La tua cronologia precedente alla morte viene copiata dal riepilogo morte di Blizzard tramite il ponte protetto di TomoDamageMeter. Quel riepilogo non è leggibile nell'istante della morte, perciò viene ritentato per circa due secondi e mezzo prima di segnare la morte come priva di dettagli leggibili.",
    ["wn_403_survival_reliability"] = "Modifica — Il numero di morti osservate viene confrontato con il contatore del gioco per la chiave. Una run coerente è segnalata come tracciamento completo, mentre una chiave presa in corsa o ricaricata a metà run è segnalata come tracciamento parziale con entrambi i valori, invece di presentare un elenco incompleto come se fosse tutto.",
    ["wn_403_survival_history"] = "Novità — La cronologia delle morti è salvata nell'istantanea della run insieme ai dati di prestazione esistenti: riaprire una chiave passata dalla Cronologia run mostra le morti che quella run ha davvero avuto invece di niente.",
    ["wn_403_survival_localization"] = "Modifica — Tutte le etichette della scheda Sopravvivenza — le schede stesse, la cronologia, lo stato del tracciamento, l'evento fatale, la timeline e i messaggi mostrati quando non c'è dettaglio — sono tradotte in tutte e sei le lingue supportate.",
    ["wn_403_bags_secure_clicks"] = "Correzione — Bags V4 non aggiunge più gestori propri di mouse, clic o trascinamento ai pulsanti oggetto protetti di Blizzard. Il modello nativo resta l'unico responsabile dell'uso degli oggetti e dei tooltip, evitando che un normale clic destro provochi ADDON_ACTION_FORBIDDEN.",
    ["wn_403_tomohdv_studio"] = "Novità — TomoHDV è ora integrato come scheda nativa della Casa d'Aste con le aree Cerca, Ricette e Scansione. Il precedente tracker mobile viene ritirato, mentre i prezzi salvati e la compatibilità dei tooltip restano disponibili.",
    ["wn_403_tomohdv_workflows"] = "Novità — La ricerca mostra query recenti, quantità, prezzi minimi attuali e prezzi scansionati, con accesso diretto alla vista Acquista di Blizzard. Le schede delle ricette tracciate elencano prezzi unitari e totali dei reagenti e consentono di cercarne uno con un clic.",
    ["wn_403_tomohdv_scan"] = "Novità — Le scansioni complete della Casa d'Aste salvano il prezzo unitario più basso osservato per ogni oggetto, mostrano l'avanzamento e rispettano l'intervallo Blizzard di 15 minuti tra le scansioni replicate.",
    ["wn_403_tomohdv_polish"] = "Modifica — TomoHDV V2 riceve navigazione centrata, selezioni persistenti, colonne flessibili, pannelli adattivi per ricerca e ricette, schede dei prezzi e un avanzamento della scansione più chiaro.",
    ["wn_403_tomohdv_safety"] = "Correzione — La scheda TomoHDV si ancora in modo sicuro all'ultima scheda nativa di Blizzard. Le personalizzazioni globali ignorano ora i tooltip integrati sensibili di Casa d'Aste, mappa e missioni per non contaminare i percorsi protetti dell'interfaccia.",
    ["wn_403_tomohdv_direct_buy"] = "Novità — TomoHDV V3 permette di acquistare direttamente dalla scheda oggetto. Selezionare un risultato interroga le offerte attuali di Blizzard e mostra il tipo d'asta, un campo quantità, il totale stimato e una riga di stato, senza uscire dalla scheda.",
    ["wn_403_tomohdv_buy_quote"] = "Novità — Il totale delle merci usa l'aggregazione per quantità di Blizzard, quindi il prezzo mostrato è il costo reale di più offerte accumulate. Un pulsante Max prende tutto il disponibile, mentre un'asta normale si risolve nell'offerta più economica che non sia tua.",
    ["wn_403_tomohdv_buy_safety"] = "Modifica — Il preventivo viene ricalcolato nel clic stesso, subito prima della chiamata protetta, così un prezzo cambiato non viene pagato su un totale obsoleto. La conferma resta quella di Blizzard e si apre sopra TomoHDV.",
    ["wn_403_tomohdv_buy_live"] = "Modifica — Il pannello d'acquisto segue il traffico della Casa d'Aste: gli aggiornamenti di ricerca rinfrescano l'offerta sul posto, un acquisto completato interroga di nuovo le offerte rimanenti e uno fallito lo segnala disattivando il pulsante fino alla prossima offerta.",
    ["wn_403_tomohdv_selection_layout"] = "Modifica — Il risultato selezionato mantiene il suo accento azzurro durante gli aggiornamenti, il vecchio pulsante Apri in Acquista scompare perché l'acquisto avviene sul posto, e colonne e schede prezzo sono state riequilibrate per fare spazio al nuovo pannello.",
    ["wn_403_tomohdv_overflow"] = "Correzione — TomoHDV V3.1 mantiene l'intero blocco di acquisto diretto dentro la scheda oggetto a ogni altezza supportata della Casa d'Aste. I controlli di quantità, totale, stato e acquisto non fuoriescono più sotto il pannello.",
    ["wn_403_tomohdv_text_limits"] = "Correzione — Pulsanti, ricerche recenti, prezzi, quantità, tipi d'asta e messaggi di stato rispettano ora larghezza e numero di righe disponibili. I nomi usano al massimo due righe e la scheda adattiva varia da 340 a 400 pixel.",
    ["wn_403_lustsound_audio"] = "Modifica — LustSound rispetta ora il canale audio di WoW selezionato, lo stato attuale del suono e il volume principale. L'opzione Forza suono è stata rimossa e TomoMod non modifica più le CVar audio globali quando l'avviso inizia o termina.",
})

TomoMod_RegisterLocale("ptBR", {
    ["wn_403_quest_journal_skin_removed"] = "Removido — O visual experimental do Diário de missões e do mapa-múndi foi removido porque causava erros no jogo. A aparência e o comportamento originais da Blizzard permanecem intactos; a aba independente de missões do mundo continua disponível.",
    ["wn_403_world_quest_tab"] = "Alteração — O antigo painel de missões do mundo ao lado do mapa foi substituído por uma aba nativa dentro do Diário de missões, reunindo missões e navegação do mapa em uma única janela.",
    ["wn_403_world_quest_cards"] = "Novidade — As missões do mundo aparecem em cartões compactos com ícone de recompensa, cor de raridade, marcador de elite, zona e tempo restante. Busca, ordenação por tempo, recompensa, zona ou nome, barra de rolagem arrastável e navegação até o mapa com um clique estão incluídas.",
    ["wn_403_world_quest_sort"] = "Correção — A ordenação das missões do mundo agora aceita tempos, dados de recompensa e IDs de missão ausentes ou não numéricos. Entradas vazias são posicionadas de forma consistente, valores iguais são desempatados pelo ID da missão e os dois sentidos de ordenação são explícitos.",
    ["wn_403_bags_separate_skin"] = "Novidade — O modo de bolsas separadas mantém as janelas individuais da Blizzard e aplica a elas um visual TomoMod completo: painéis e cabeçalhos escuros, bordas azuis, títulos Poppins, espaços rebaixados, ícones recortados e destaque ao passar o mouse. Voltar ao modo combinado ou desativar as bolsas restaura o visual nativo original.",
    ["wn_403_bags_tracked_currencies"] = "Novidade — A barra lateral do Bags V4 agora lista cada moeda marcada Mostrar na mochila em blocos compactos de duas colunas, com ícone, quantidade formatada e dica nativa. A seção localizada aparece apenas quando há moedas rastreadas e é atualizada quando seus dados mudam.",
    ["wn_403_bags_currency_reliability"] = "Correção — Ocultar a mochila da Blizzard no modo combinado podia reduzir para um a capacidade calculada de moedas rastreadas. O TomoMod agora preserva os três espaços tradicionais apenas nesse modo e lê diretamente o estado persistente isShowInBackpack, para que moedas adicionais não desapareçam mais.",
    ["wn_403_color_picker_skin"] = "Novidade — O seletor de cores global da Blizzard agora tem um visual TomoMod completo, com corpo, cabeçalho e rodapé escuros em camadas, bordas azuis, fonte Poppins e controles combinando. O campo hexadecimal, as amostras de cor, as áreas de valor e alfa e o controle de opacidade seguem o mesmo estilo.",
    ["wn_403_color_picker_compatibility"] = "Alteração — O visual oferece suporte ao layout Retail atual e ao layout antigo do ColorPickerFrame, é inicializado quando o seletor da Blizzard sob demanda fica disponível e é reaplicado sempre que a janela abre. A Blizzard continua responsável pela seleção de cor e pelas funções de confirmação e cancelamento.",
    ["wn_403_color_picker_buttons"] = "Correção — Os botões de painel Retail não redesenham mais suas texturas persistentes Left, Middle e Right sobre o visual TomoMod. O botão de fechar personalizado também preserva a função de cancelamento original da Blizzard e os valores de cor anteriores.",
    ["wn_403_waypoint_inner_ring"] = "Alteração — O marcador de ponto de destino agora mantém apenas o anel interno compacto. O grande brilho externo translúcido e seus ajustes de cor e tamanho foram removidos para deixar o marcador mais limpo, enquanto o feixe, o ponto central e a seta de navegação mantêm o comportamento atual.",
    ["wn_403_mplus_cast_focus"] = "Novidade — O Estúdio Mítica+ recebe a opção experimental Placas focadas em conjurações, desativada por padrão. Em uma chave ativa com pelo menos dois inimigos trash relevantes em combate, uma conjuração ou canalização mantém sua origem visível e esmaece temporariamente as outras placas de trash em combate.",
    ["wn_403_mplus_cast_focus_safety"] = "Alteração — Alvo e foco permanecem sempre visíveis, chefes e unidades amistosas nunca são filtrados, e tanques continuam vendo inimigos sem ameaça ou com ameaça baixa. Todas as placas são restauradas imediatamente quando não há conjurações ativas ou a opção é desativada.",
    ["wn_403_mplus_cast_focus_runtime"] = "Interno — O foco em conjurações altera apenas a opacidade do elemento visual do TomoMod, nunca a placa protegida nem a área clicável da Blizzard. Sua execução leve fica no módulo de Placas sempre carregado, então o Estúdio Mítica+ sob demanda não precisa permanecer aberto durante o combate.",
    ["wn_403_survival_tab"] = "Novidade — A Análise de run Mítica+ ganha uma aba Sobrevivência ao lado do Resumo. As duas visões compartilham a mesma janela, então o resumo da run, o desempenho do grupo e as parciais ficam a um clique da análise de mortes.",
    ["wn_403_survival_chronology"] = "Novidade — A aba Sobrevivência lista todas as mortes registradas durante a chave em ordem cronológica, com o tempo de run e a cor de classe do jogador. Selecionar uma linha abre essa morte no painel de detalhe.",
    ["wn_403_survival_detail"] = "Novidade — Suas próprias mortes são exibidas por completo: o evento fatal com ícone, nome, dano e overkill, sua vida máxima e os dez últimos eventos antes da morte, cada um com o tempo que o separa do golpe fatal e a vida que restava.",
    ["wn_403_survival_collector"] = "Novidade — O coletor de mortes agora é carregado com o próprio TomoMod, e não com o Estúdio Mítica+ sob demanda. O rastreamento começa junto com a chave, então uma run não se perde mais porque o Estúdio ainda não havia sido aberto.",
    ["wn_403_survival_unit_events"] = "Alteração — As mortes são lidas das transições de estado das unidades em vez do registro de combate, protegido no cliente atual. Os eventos de vida e de estado do grupo fornecem a mesma cronologia sem tocá-lo.",
    ["wn_403_survival_recap_bridge"] = "Alteração — Sua cronologia anterior à morte é copiada do resumo de morte da Blizzard pela ponte protegida do TomoDamageMeter. Esse resumo não fica legível no instante da morte, então é tentado novamente por cerca de dois segundos e meio antes de a morte ser marcada como sem detalhe legível.",
    ["wn_403_survival_reliability"] = "Alteração — O número de mortes observadas é confrontado com o próprio contador do jogo para a chave. Uma run coerente é informada como rastreamento completo, enquanto uma chave iniciada tarde ou recarregada no meio da run é informada como rastreamento parcial com os dois números, em vez de apresentar uma lista incompleta como se fosse tudo.",
    ["wn_403_survival_history"] = "Novidade — A cronologia de mortes é gravada no instantâneo da run junto aos dados de desempenho existentes, então reabrir uma chave antiga pelo Histórico de runs mostra as mortes que aquela run realmente teve em vez de nada.",
    ["wn_403_survival_localization"] = "Alteração — Todos os rótulos da aba Sobrevivência — as próprias abas, a cronologia, o estado do rastreamento, o evento fatal, a linha do tempo e as mensagens exibidas quando não há detalhe — estão traduzidos nos seis idiomas suportados.",
    ["wn_403_bags_secure_clicks"] = "Correção — Bags V4 não adiciona mais manipuladores próprios de mouse, clique ou arraste aos botões de item protegidos da Blizzard. O modelo nativo continua sendo o único responsável pelo uso de itens e pelas dicas, evitando que um clique direito comum cause ADDON_ACTION_FORBIDDEN.",
    ["wn_403_tomohdv_studio"] = "Novidade — TomoHDV agora está integrado como uma aba nativa da Casa de Leilões com as áreas Busca, Receitas e Escaneamento. O antigo rastreador flutuante foi retirado, mas seus preços salvos e a compatibilidade das dicas permanecem disponíveis.",
    ["wn_403_tomohdv_workflows"] = "Novidade — A busca mostra pesquisas recentes, quantidades, preços mínimos atuais e preços escaneados, com acesso direto à tela Comprar da Blizzard. As fichas de receitas rastreadas exibem preços unitários e totais dos reagentes e permitem pesquisar um componente com um clique.",
    ["wn_403_tomohdv_scan"] = "Novidade — Os escaneamentos completos da Casa de Leilões armazenam o menor preço unitário observado de cada item, mostram o progresso e respeitam o intervalo de 15 minutos da Blizzard entre escaneamentos replicados.",
    ["wn_403_tomohdv_polish"] = "Alteração — TomoHDV V2 recebe navegação centralizada, seleções persistentes, colunas flexíveis, painéis adaptáveis de busca e receitas, cartões de preços e um progresso de escaneamento mais claro.",
    ["wn_403_tomohdv_safety"] = "Correção — A aba TomoHDV se ancora com segurança à última aba nativa da Blizzard. As personalizações globais agora ignoram dicas integradas sensíveis da Casa de Leilões, do mapa e das missões para não contaminar caminhos protegidos da interface.",
    ["wn_403_tomohdv_direct_buy"] = "Novidade — O TomoHDV V3 permite comprar direto da ficha do item. Selecionar um resultado consulta as ofertas atuais da Blizzard e mostra o tipo de leilão, um campo de quantidade, o total estimado e uma linha de estado, sem sair da aba.",
    ["wn_403_tomohdv_buy_quote"] = "Novidade — O total das mercadorias usa a agregação por quantidade da própria Blizzard, então o preço exibido é o custo real de consumir várias ofertas empilhadas. Um botão Máx. pega tudo o que está disponível, enquanto um leilão comum resolve para a listagem mais barata que não seja sua.",
    ["wn_403_tomohdv_buy_safety"] = "Alteração — O orçamento é recalculado dentro do próprio clique, logo antes da chamada protegida, para que um preço que mudou não seja pago com um total desatualizado. A confirmação continua sendo a da Blizzard e abre sobre o TomoHDV.",
    ["wn_403_tomohdv_buy_live"] = "Alteração — O painel de compra acompanha o movimento da Casa de Leilões: atualizações de busca renovam a oferta no lugar, uma compra concluída reconsulta as ofertas restantes e uma que falhou avisa e desativa o botão até a próxima oferta.",
    ["wn_403_tomohdv_selection_layout"] = "Alteração — O resultado selecionado mantém seu destaque azul durante as atualizações, o antigo botão Abrir em Comprar sai de cena porque a compra acontece no lugar, e as colunas e os cartões de preço foram reequilibrados para abrir espaço ao novo painel.",
    ["wn_403_tomohdv_overflow"] = "Correção — TomoHDV V3.1 mantém todo o bloco de compra direta dentro da ficha do item em qualquer altura compatível da Casa de Leilões. Os controles de quantidade, total, estado e compra não ultrapassam mais a parte inferior do painel.",
    ["wn_403_tomohdv_text_limits"] = "Correção — Botões, buscas recentes, preços, quantidades, tipos de leilão e mensagens de estado agora respeitam a largura e o número de linhas disponíveis. Os nomes usam no máximo duas linhas e a ficha adaptável varia entre 340 e 400 pixels.",
    ["wn_403_lustsound_audio"] = "Alteração — LustSound agora respeita o canal de áudio do WoW selecionado, o estado atual do som e o volume principal. A opção Forçar som foi removida e o TomoMod não altera mais as CVars globais de áudio quando o alerta começa ou termina.",
})
